package com.salespunch360.mobile.ui.account.accounting
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun JournalScreen(padding:PaddingValues,opening:Boolean=false,vm:AccountAccountingViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;var from by remember{mutableStateOf("")};var to by remember{mutableStateOf("")};var branch by remember{mutableStateOf("")};val rows=s.journalRows;Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){Row{OutlinedTextField(s.query,vm::search,label={Text("Search number, reference or narration")},modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton({vm.newJournal(opening)},enabled=s.data["capabilities"]?.jsonObject?.get(if(opening)"canPostOpening" else "canPost")?.jsonPrimitive?.booleanOrNull==true&&!s.saving){Icon(Icons.Default.Add,"New journal")}};Row{OutlinedTextField(from,{from=it},label={Text("From")},modifier=Modifier.weight(1f));OutlinedTextField(to,{to=it},label={Text("To")},modifier=Modifier.weight(1f));Option("Branch",branch,s.data.array("branches")){branch=it}};Button({vm.history(branch,from,to)},enabled=!s.loading){Text("Apply filters")};if(s.hasMore)TextButton({vm.history(more=true)},enabled=!s.loading){Text("Load more")};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(rows,key={it.str("id")}){x->ListItem(headlineContent={Text(x.str("journalNumber"),fontWeight=FontWeight.Bold)},supportingContent={Text("${x.str("entryDate").take(10)} · ${x.str("narration")}")},trailingContent={Text(x.str("status"))},modifier=Modifier.clickable{vm.openJournal(x.str("id"))})}}};s.draft?.let{JournalEditor(it,s.data,s.saving,s.error,vm::draft,vm::close,vm::saveJournal)};s.journal?.let{JournalDetail(it,s.saving,s.error,s.data["capabilities"]?.jsonObject?.get("canPost")?.jsonPrimitive?.booleanOrNull==true,vm::close,vm::reverse)}}
@Composable private fun JournalEditor(d:JournalDraft,data:JsonObject,saving:Boolean,error:String?,change:(JournalDraft)->Unit,close:()->Unit,save:()->Unit){AlertDialog(onDismissRequest=close,title={Text(if(d.opening)"Opening balance" else "Manual journal")},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{error?.let{Text(it,color=MaterialTheme.colorScheme.error)}};item{Option("Financial year",d.financialYearId,data.array("financialYears")){change(d.copy(financialYearId=it))}};item{Option("Branch",d.branchId,data.array("branches")){change(d.copy(branchId=it))}};item{OutlinedTextField(d.date,{change(d.copy(date=it))},label={Text("Entry date")})};item{OutlinedTextField(d.reference,{change(d.copy(reference=it))},label={Text("Reference")})};item{OutlinedTextField(d.narration,{change(d.copy(narration=it))},label={Text("Narration")})};itemsIndexed(d.lines){i,l->Card{Column(Modifier.padding(8.dp)){Option("Ledger",l.ledgerId,data.array("ledgerAccounts").filter{it.jsonObject["allowPosting"]?.jsonPrimitive?.booleanOrNull==true&&it.jsonObject["isActive"]?.jsonPrimitive?.booleanOrNull==true}){v->change(d.copy(lines=d.lines.mapIndexed{n,x->if(n==i)x.copy(ledgerId=v)else x}))};Option("Cost centre (optional)",l.costCentreId,data.array("costCentres")){v->change(d.copy(lines=d.lines.mapIndexed{n,x->if(n==i)x.copy(costCentreId=v)else x}))};Row{OutlinedTextField(l.debit,{v->change(d.copy(lines=d.lines.mapIndexed{n,x->if(n==i)x.copy(debit=v)else x}))},label={Text("Debit")},modifier=Modifier.weight(1f));OutlinedTextField(l.credit,{v->change(d.copy(lines=d.lines.mapIndexed{n,x->if(n==i)x.copy(credit=v)else x}))},label={Text("Credit")},modifier=Modifier.weight(1f))};if(d.lines.size>2)TextButton({change(d.copy(lines=d.lines.filterIndexed{n,_->n!=i}))}){Text("Remove line")}}}};item{TextButton({change(d.copy(lines=d.lines+JournalLineDraft()))},enabled=!saving&&d.lines.size<500){Text("Add debit/credit line")}}}},confirmButton={Button(enabled=!saving&&d.lines.size>=2&&d.lines.all{it.ledgerId.isNotBlank()},onClick=save){Text("Post on server")}},dismissButton={TextButton(close,enabled=!saving){Text("Cancel")}})}
@Composable private fun JournalDetail(x:JsonObject,saving:Boolean,error:String?,canReverse:Boolean,close:()->Unit,reverse:(String,String,String)->Unit){var reason by remember{mutableStateOf("")};var date by remember{mutableStateOf(java.time.LocalDate.now().toString())};AlertDialog(onDismissRequest=close,title={Text(x.str("journalNumber"))},text={LazyColumn{item{error?.let{Text(it,color=MaterialTheme.colorScheme.error)}};item{Text("${x.str("entryDate").take(10)} · ${x.str("status")}")};item{Text(x.str("narration"))};items(x.array("lines")){e->val l=e.jsonObject;ListItem(headlineContent={Text(l["ledgerAccount"]?.jsonObject?.str("name").orEmpty())},supportingContent={Text(l.str("description"))},trailingContent={Text("Dr ${l.str("debit")} · Cr ${l.str("credit")}")})};if(canReverse&&x.str("status")=="POSTED"){item{OutlinedTextField(date,{date=it},label={Text("Reversal date")})};item{OutlinedTextField(reason,{reason=it},label={Text("Reversal reason")})}}}},confirmButton={if(canReverse&&x.str("status")=="POSTED")Button(enabled=!saving&&reason.trim().length>=3,onClick={reverse(x.str("id"),date,reason)}){Text("Reverse on server")}else TextButton(close){Text("Close")}},dismissButton={TextButton(close){Text("Close")}})}
@OptIn(ExperimentalMaterial3Api::class) @Composable internal fun Option(label:String,value:String,values:List<JsonElement>,set:(String)->Unit){var open by remember{mutableStateOf(false)};val selected=values.map{it.jsonObject}.firstOrNull{it.str("id")==value};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(selected?.str("name")?.ifBlank{null}?:selected?.str("code").orEmpty(),{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{e->val x=e.jsonObject;DropdownMenuItem({Text(x.str("name").ifBlank{x.str("code")})},{set(x.str("id"));open=false})}}}}
